#!/usr/bin/env node
/**
 * Local gallery of every MultiStack e-mail, built from the reviewed HTML
 * snapshots in supabase/functions/_shared/email/__snapshots__/ (generated by
 * `npx vitest run supabase/functions/_shared/email`). Each e-mail is shown in
 * a 640 px (desktop) and a 375 px (mobile) frame, exactly like an inbox would
 * size it. Sends nothing.
 *
 *   npm run email:preview            → writes email-previews/index.html
 *   npx vitest run supabase/functions/_shared/email -u   → refresh snapshots after an intended change
 */
import { readdirSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const snapDir = join(root, "supabase", "functions", "_shared", "email", "__snapshots__");
const outDir = join(root, "email-previews");

const LABELS = {
  "auth-password-recovery": "Recuperación de contraseña",
  "auth-confirm-signup": "Confirmación de cuenta",
  "auth-email-change": "Confirmación de nuevo correo",
  "auth-invite": "Invitación",
  "welcome": "Bienvenida",
  "ticket-reply": "Respuesta a ticket (solicitud)",
  "ticket-reply-project": "Respuesta a ticket (proyecto, sin enlace)",
  "contact-internal": "Contacto — notificación interna",
  "contact-internal-phone-only": "Contacto — solo teléfono",
};

const files = readdirSync(snapDir).filter((f) => f.endsWith(".html")).sort(
  (a, b) => Object.keys(LABELS).indexOf(a.replace(".html", "")) - Object.keys(LABELS).indexOf(b.replace(".html", "")),
);
if (files.length === 0) {
  console.error("No snapshots found. Run: npx vitest run supabase/functions/_shared/email");
  process.exit(1);
}

mkdirSync(outDir, { recursive: true });
const sections = files.map((f) => {
  const name = f.replace(".html", "");
  const src = relative(outDir, join(snapDir, f)).split("\\").join("/");
  return `
  <section id="${name}">
    <h2>${LABELS[name] ?? name} <a href="${src}" target="_blank">abrir</a></h2>
    <div class="frames">
      <figure><iframe src="${src}" width="640" height="960" title="${name} escritorio"></iframe><figcaption>Escritorio · 640 px</figcaption></figure>
      <figure><iframe src="${src}" width="375" height="960" title="${name} móvil"></iframe><figcaption>Móvil · 375 px</figcaption></figure>
    </div>
  </section>`;
}).join("\n");

writeFileSync(join(outDir, "index.html"), `<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8"><title>Correos — MultiStack Systems</title>
<style>
  body{margin:0;padding:24px 16px 64px;background:#e4e4e7;font:14px/1.5 -apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#18181b}
  h1{margin:0 0 4px;font-size:20px} p.lead{margin:0 0 24px;color:#52525b}
  nav{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:24px} nav a{padding:4px 10px;border:1px solid #d4d4d8;border-radius:999px;background:#fff;color:#18181b;text-decoration:none}
  section{margin:0 0 40px} h2{font-size:16px;margin:0 0 12px} h2 a{font-size:12px;font-weight:400;color:#71717a;margin-left:8px}
  .frames{display:flex;flex-wrap:wrap;gap:20px;align-items:flex-start}
  figure{margin:0} iframe{display:block;border:1px solid #d4d4d8;border-radius:8px;background:#fff} figcaption{margin-top:6px;font-size:12px;color:#71717a}
</style></head><body>
<h1>Correos de MultiStack Systems</h1>
<p class="lead">Vista previa generada desde las instantáneas revisadas (datos de ejemplo, sin envíos).</p>
<nav>${files.map((f) => `<a href="#${f.replace(".html", "")}">${LABELS[f.replace(".html", "")] ?? f}</a>`).join("")}</nav>
${sections}
</body></html>
`);

const index = join(outDir, "index.html");
console.log(`Gallery: ${pathToFileURL(index).href}  (${files.length} e-mails)`);
